+      var t = themeTokens();
+
+      // Scatter: x=cost (log), y=accuracy
+      var scatterData = MODELS.map(function(m){
+        return {
+          x: m.cost,
+          y: m.accuracy,
+          r: Math.max(4, Math.min(12, 3.2 + m.cost / 3.6)),
+          label: m.model,
+          family: m.family,
+          cost: m.cost,
+          acc: m.accuracy
+        };
+      });
+
+      ChartManager.safeInit('scatterCostAccuracy', {
+        type: 'bubble',
+        data: {
+          datasets: Object.keys(FAMILY_COLORS).map(function(fam){
+            return {
+              label: fam,
+              data: scatterData.filter(function(p){ return p.family === fam; }),
+              backgroundColor: (FAMILY_COLORS[fam] || '#94a3b8') + 'B3',
+              borderColor: (FAMILY_COLORS[fam] || '#94a3b8'),
+              borderWidth: 1.5,
+              hoverBorderWidth: 2.5
+            };
+          })
+        },
+        options: {
+          responsive: true,
+          maintainAspectRatio: false,
