+              }
+            },
+            legend: {
+              position: 'bottom',
+              labels: { color: t.sub, boxWidth: 10, boxHeight: 10, usePointStyle: true }
+            }
+          },
+          scales: {
+            x: {
+              type: 'logarithmic',
+              title: { display: true, text: 'Cost per benchmark run (USD, log scale)', color: t.sub, font: { size: 12, weight: '600' } },
+              ticks: {
+                color: t.sub,
+                callback: function(v){
+                  // show common tick labels
+                  if (v === 1 || v === 2 || v === 5 || v === 10 || v === 20 || v === 50) return '$' + v;
+                  return '';
+                }
+              },
+              grid: { color: t.grid }
+            },
+            y: {
+              title: { display: true, text: 'Accuracy (% correct)', color: t.sub, font: { size: 12, weight: '600' } },
+              suggestedMin: 70,
+              suggestedMax: 90,
+              ticks: { color: t.sub },
+              grid: { color: t.grid }
+            }
+          }
+        }
+      });
+
+      // Bar: edit format %
+      var sortedByFormat = MODELS.slice().sort(function(a,b){ return b.formatPct - a.formatPct; });
+      ChartManager.safeInit('barFormat', {
+        type: 'bar',
+        data: {
+          labels: sortedByFormat.map(function(m){ return m.model; }),
+          datasets: [{
+            label: 'Correct format (%)',
+            data: sortedByFormat.map(function(m){ return m.formatPct; }),
+            backgroundColor: sortedByFormat.map(function(m){ return (FAMILY_COLORS[m.family] || '#94a3b8') + 'B3'; }),
+            borderColor: sortedByFormat.map(function(m){ return (FAMILY_COLORS[m.family] || '#94a3b8'); }),
+            borderWidth: 1.2
+          }]
+        },
+        options: {
+          indexAxis: 'y',
+          responsive: true,
+          maintainAspectRatio: false,
+          plugins: {
+            tooltip: {
+              enabled: true,
+              callbacks: {
+                label: function(ctx){
+                  var m = sortedByFormat[ctx.dataIndex];
+                  return ctx.raw.toFixed(1) + '% · ' + m.format + ' · ' + m.family;
+                }
+              }
+            },
+            legend: { display: false }
+          },
+          scales: {
+            x: {
+              suggestedMin: 84,
+              suggestedMax: 98,
+              ticks: { color: t.sub },
+              grid: { color: t.grid }
+            },
+            y: {
