cat > output/render_poster.mjs <<'MJS'
import { chromium } from 'playwright';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const htmlPath = path.resolve(__dirname, 'aider-llm-polyglot-leaderboard-2025-poster.html');
const outPng = path.resolve(__dirname, '..', 'output', 'final_poster.png');

const viewport = { width: 1040, height: 1500 };

const sleep = (ms) => new Promise(r => setTimeout(r, ms));

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport, deviceScaleFactor: 2 });

  await page.goto('file://' + htmlPath, { waitUntil: 'load' });

  // Wait for charts to render and fonts to settle
  await page.waitForTimeout(800);
  await page.evaluate(async () => {
    try {
      // Ensure fonts loaded
      // eslint-disable-next-line no-undef
      if (document.fonts && document.fonts.status !== 'loaded') await document.fonts.ready;
    } catch {}
  });
  await page.waitForTimeout(300);

  // Expand viewport to full document height (portrait poster)
  const fullHeight = await page.evaluate(() => {
    const body = document.body;
    const html = document.documentElement;
    return Math.max(
      body.scrollHeight,
      body.offsetHeight,
      html.clientHeight,
      html.scrollHeight,
      html.offsetHeight
    );
  });

  await page.setViewportSize({ width: viewport.width, height: Math.min(2600, Math.max(1600, Math.ceil(fullHeight))) });
  await page.waitForTimeout(300);

  await page.screenshot({ path: outPng, fullPage: true, type: 'png' });

  await browser.close();
  console.log('Wrote', outPng);
})();
MJS

